function validate([s1, s2]) {
  if (typeof s1 !== 'string' || typeof s2 !== 'string' || s1.length !== s2.length) return 's1 and s2 must have the same length.';
  if (s1.length < 1) return 'The strings need at least one character.';
  if (!/^[a-z]+$/.test(s1) || !/^[a-z]+$/.test(s2)) return 'Use only lowercase English letters.';
  return null;
}

