function checkStrings(s1, s2) {
  const counts = [new Array(26).fill(0), new Array(26).fill(0)];

  for (let i = 0; i < s1.length; i++) {
    const parity = i % 2;
    counts[parity][s1.charCodeAt(i) - 97]++;
    counts[parity][s2.charCodeAt(i) - 97]--;
  }

  for (const group of counts) {
    for (const count of group) {
      if (count !== 0) {
        return false;
      }
    }
  }
  return true;
}

