function checkStrings(s1, s2) {
  // Positions of one parity can be rearranged freely among themselves, so compare each parity's letters sorted.
  const sortedAt = (s, start) => {
    const letters = [];
    for (let i = start; i < s.length; i += 2) letters.push(s[i]);
    return letters.sort().join('');
  };
  return sortedAt(s1, 0) === sortedAt(s2, 0) && sortedAt(s1, 1) === sortedAt(s2, 1);
}

