function generate(rand, size) {
  const n = size === 'large' ? 10000 - Math.floor(rand() * 3) : 1 + Math.floor(rand() * 8);
  const alphabet = size === 'large' ? 26 : 1 + Math.floor(rand() * 3);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * alphabet));
  const s1 = Array.from({ length: n }, letter);
  const mode = rand();
  let s2;
  if (mode < 0.25) {
    // A fully random second string: usually unreachable.
    s2 = Array.from({ length: n }, letter);
  } else {
    // Shuffle the even positions and the odd positions separately, which is always reachable.
    s2 = s1.slice();
    for (let start = 0; start < 2; start++) {
      for (let i = n - 1 - ((n - 1 - start) % 2); i >= start + 2; i -= 2) {
        const j = start + 2 * Math.floor(rand() * ((i - start) / 2 + 1));
        [s2[i], s2[j]] = [s2[j], s2[i]];
      }
    }
    // Sometimes break it: swap a neighbouring pair, or change one letter.
    if (mode < 0.55 && n > 1) {
      const i = Math.floor(rand() * (n - 1));
      [s2[i], s2[i + 1]] = [s2[i + 1], s2[i]];
    } else if (mode < 0.7) {
      s2[Math.floor(rand() * n)] = letter();
    }
  }
  return [s1.join(''), s2.join('')];
}
